import Phaser from 'phaser';
import {Battle,data,nations,newCampaign,parseSave,recruit,unitKey,expand,maxHP,weaponStats,xpThresholds,seedRandom,type Campaign,type Fighter,type Hero,type Nation,type Item} from './model';
