const app=document.querySelector<HTMLDivElement>('#app')!;
// Static URL strings let Vite preserve relative paths for GitHub project Pages.
const worldURL=new URL('../public/art/remastered/world.webp',import.meta.url).href;
const battleURL=new URL('../public/art/remastered/battle.webp',import.meta.url).href;
const cityURL=new URL('../public/art/remastered/city.webp',import.meta.url).href;
const lineupURL=new URL('../public/art/remastered/lineup.webp',import.meta.url).href;
const combatSheetURL=new URL('../public/art/remastered/combat-sheet.webp',import.meta.url).href;
let preset=loadRenderPreset();
let showTownNames=false;
let mapScene:MapScene|null=null;
let pendingWorldFocus='';
let campaign:Campaign|null=null,view='world',selected='',game:Phaser.Game|null=null,battle:Battle|null=null,battleScene:BattleScene|null=null;
let checkpoint:Campaign|null=null;
const rootClock=new RootClock();
const idleSceneClock=new IdleSceneClock(rootClock);
let worldPaused=false;
let battleMapId=0;
let armyAbilityTarget:ArmyAbilityKind|null=null;
let paused=false,speed=1,control='hero',resultShown=false;
const heroControls=new HeroControls();
const SAVE='feudalism-campaign-v1';
try{const s=localStorage.getItem(SAVE);if(s)campaign=readCampaignSave(s);}catch{ /* A blocked or invalid browser store must not prevent boot. */ }
selected=campaign?.town??'Trapezus';
const esc=(s:unknown)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const money=(n:number)=>Math.round(n).toLocaleString();
function notify(text:string){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=text;document.body.append(el);setTimeout(()=>el.remove(),4200);}
function save(){if(!campaign)return;try{localStorage.setItem(SAVE,JSON.stringify(campaign));}catch{notify('Browser storage is unavailable. Export your save to keep this campaign.');}}
function modal(html:string){document.querySelector('.overlay')?.remove();const overlay=document.createElement('div');overlay.className='overlay';overlay.innerHTML=`<section class="dialog" role="dialog" aria-modal="true">${html}</section>`;document.body.append(overlay);overlay.querySelector<HTMLElement>('button')?.focus();}
function closeModal(){document.querySelector('.overlay')?.remove();}
function bind(selector:string,fn:(e:Event)=>void){document.querySelectorAll(selector).forEach(el=>el.addEventListener('click',fn));}
function header(){const c=campaign;return `<header class="header"><div class="brand"><div class="crest" aria-hidden="true">${icon('swords')}</div><div><h1>Feudalism</h1><div class="eyebrow">Remastered · A new age of conquest</div></div></div><div class="resources">${c?`<div class="resource gold">${money(c.gold)} <small>Gold pieces</small></div><button class="resource army-summary" id="army-summary" aria-label="View your army"><b id="army-total">${battle?battle.survivors().length:c.army.length}</b><small>Soldiers · View army</small></button><div class="resource">${c.captured.length} / 32<small>Towns held</small></div>`:''}<label class="preset-control"><span>Graphics</span><select id="graphics-preset" aria-label="Graphics preset">${RENDER_PRESET_IDS.map(id=>`<option value="${id}" ${preset.id===id?'selected':''}>${RENDER_PRESETS[id].label}</option>`).join('')}</select></label><button class="tiny ghost" id="help" aria-label="Open field guide">${icon('help')}</button></div></header>`;}
function footer(){return `<footer class="footer"><span>PRESENTATION · STAGE 02 · ${esc(import.meta.env.VITE_BUILD_ID??'local')}<br><span style="opacity:.65">Original game by Vitaly Zaborov · 2007</span></span><span>${campaign?'Campaign autosaves between battles · ':''}<a href="https://www.kongregate.com/en/games/vitaly/feudalism" target="_blank" rel="noopener">Original game ↗</a></span></footer>`;}
function render(){if(campaign){world(campaign);if(view==='city'&&!world(campaign).town)view='world';}resetHeroControls();if(game){game.destroy(true);game=null;}battleScene=null;mapScene=null;app.innerHTML=`<main class="app-shell" data-preset="${preset.id}" data-view="${battle?'battle':campaign?view:'start'}">${header()}${campaign?`<nav aria-label="Campaign"><button data-view="world" class="${view==='world'?'active':''}">${icon('compass')}<span>World map</span></button><button data-view="city" class="${view==='city'?'active':''}">${icon('town')}<span>City</span></button><button data-view="army" class="${view==='army'?'active':''}">${icon('banner')}<span>Army</span></button><button data-view="hero" class="${view==='hero'?'active':''}">${icon('hero')}<span>Hero</span></button><button data-view="inventory" class="${view==='inventory'?'active':''}">${icon('bag')}<span>Inventory</span></button><button data-view="journal" class="${view==='journal'?'active':''}">${icon('book')}<span>Journal</span></button><button data-view="atelier" class="${view==='atelier'?'active':''}">${icon('art')}<span>Art direction</span></button></nav>`:''}${campaign&&!battle?(view==='world'?paymentPanel():companyStrip()+paymentPanel()):''}<div id="content"></div>${campaign&&!battle&&view==='world'?companyStrip():''}${footer()}</main>`;document.querySelector('nav button.active')?.setAttribute('aria-current','page');bind('#help',showHelp);bind('#army-summary',showCompany);bind('[data-company]',showCompany);bind('[data-claim-payment]',claimPayment);bind('[data-payment-town]',e=>travelToTown((e.currentTarget as HTMLElement).dataset.paymentTown!));bind('#track-contract',()=>{view='world';render();document.querySelector<HTMLButtonElement>('#quest-route')?.click();});document.querySelector<HTMLSelectElement>('#graphics-preset')?.addEventListener('change',e=>{const id=(e.target as HTMLSelectElement).value as RenderPresetId;preset=RENDER_PRESETS[id];saveRenderPreset(id);render();notify(`${preset.label} graphics applied. Campaign unchanged.`);});bind('nav [data-view]',e=>{if(battle)return;const next=(e.currentTarget as HTMLElement).dataset.view!;if(next==='city'&&!world(campaign!).town){notify('Reach a town before entering its city.');return;}view=next;render();});if(!campaign){renderStart();return;}if(battle){renderBattle();return;}if(view==='world')renderWorld();else if(view==='army')renderArmy();else if(view==='hero')renderHero();else if(view==='inventory')renderInventory();else if(view==='city')renderCity();else if(view==='atelier')renderAtelier();else renderJournal();}
function showHelp(){if(battle){paused=true;resetHeroControls();document.querySelector('#pause')!.textContent='Resume';refreshSupplyButtons();syncBattleHUD();}modal(`<div class="eyebrow">Your field guide</div><h2>A world to conquer.</h2><p>Select a town and travel toward it, or tap the map to choose waypoints. Land and sea boundaries can block a straight route. Rent ships at harbors, buy mounts at stables, and collect quest payment at town halls. Earn gold from town contracts before attacking larger garrisons. Enemy nations close their shops after you attack.</p><p>In battle, tap the ground to move your hero; use Attack to strike in the direction your hero faces. Select <b>Army</b> to order all soldiers. <b>Hold</b> keeps them in position; <b>Charge</b> restores their AI. Use the on-screen direction pad and hold Attack, or WASD/arrows plus Space/0 on a keyboard. Shift switches weapons; P pauses. Combat pauses when this app goes into the background.</p><p>On iPhone/iPad: open the published link in Safari, tap Share → Add to Home Screen. Once the offline cache is ready, you can play without a connection. Saves stay on this device; export to transfer them.</p><div class="notice">Alpha fidelity: troop stats, town rosters and core formulas are extracted from the SWF. Touch orders, battle scheduling and rendering are reconstructed. World travel, sea routes, mounts and town-hall rewards are now integrated. One controlled original-runtime battle matches the reconstruction. Broader parity checks, physical device acceptance and Flash save imports remain pending.</div><br><button class="primary full" id="close-help">Return to campaign</button>`);bind('#close-help',closeModal);}
function companyPortrait(key:string){const u=data.units[key];if(!u.WEAPON_PRI||u.WEAPON_PRI.TYPE==='Fist')return '<span class="company-portrait unarmed-portrait" aria-hidden="true">✊</span>';const ranged=(u.WEAPON_PRI?.rng??0)>0;const position=ranged?'66.6%':u.WEAPON_PRI?.TYPE==='Spear'?'100%':'33.3%';return `<span class="company-portrait" style="background-image:url('${lineupURL}');background-position:${position} 50%" aria-hidden="true"></span>`;}
function companyStrip(){const c=campaign!,roster=companyRoster(c);return `<section class="company-overview" aria-label="Your company"><div class="company-heading"><b>Your company</b><span>${c.army.length} soldiers + your hero</span><button data-company>View full roster</button></div><div class="company-cards"><div class="company-card"><span class="hero-token" aria-hidden="true">♜</span><div><b>${esc(c.hero.NAME)}</b><small>Hero · Level ${c.hero.LEVEL}</small></div><strong>×1</strong></div>${roster.map(({key,count,unit})=>`<button class="company-card" data-company>${companyPortrait(key)}<span><b>${esc(unit.NAME)}</b><small>${esc(unit.WEAPON_PRI?.NAME??'Unarmed')}${unit.HORSE?' · Mounted':''}</small></span><strong>×${count}</strong></button>`).join('')||'<p>No soldiers remain. Recruit in an owned town.</p>'}</div></section>`;}
function showCompany(){if(!campaign)return;if(!battle){view='army';render();return;}paused=true;resetHeroControls();document.querySelector('#pause')!.textContent='Resume';refreshSupplyButtons();syncBattleHUD();const roster=companyRoster(campaign,battle);modal(`<h2>Your surviving army</h2><p>${roster.reduce((sum,r)=>sum+r.count,0)} soldiers including reserves. Your hero is separate.</p>${roster.map(({key,count})=>troopRow(key,false,count)).join('')||'<p>No soldiers remain.</p>'}<button class="primary full" id="close-company">Back to paused battle</button>`);bind('#close-company',closeModal);}
function paymentPanel(){const c=campaign!,payments=pendingPayments(c);return `${payments.length?`<section class="payment-panel" aria-label="Uncollected contract payments"><h3>Contract payment awaiting collection</h3><p>These payments are separate from the ${money(c.gold)} gp in your purse. Arriving does not collect them.</p>${payments.map(payment=>`<div class="payment-row"><span><b>${money(payment.total)} gp</b> · ${esc(data.towns[payment.town].NAME)} town hall${payment.count>1?` · ${payment.count} payments`:''}</span>${payment.canCollect?`<button class="primary" data-claim-payment>Collect ${money(payment.next)} gp</button>`:`<button data-payment-town="${payment.town}">Travel to collect</button>`}</div>`).join('')}</section>`:''}${c.quest?`<section class="contract-tracker"><span><b>Combat contract still active</b> · Defeat ${c.quest.count} marked rogues, then collect ${money(c.quest.reward)} gp at ${esc(data.towns[c.quest.town].NAME)}. Road encounters do not complete this contract.</span><button id="track-contract">Track contract rogues</button></section>`:''}`;}
function claimPayment(){const paid=collectTownReward(campaign!);if(!paid){notify('No payment is available at this town hall.');return;}save();render();notify(`Collected ${money(paid)} gp. Purse: ${money(campaign!.gold)} gp.`);}
function renderStart(){document.querySelector('#content')!.innerHTML=`<div class="intro remaster-intro" style="--intro-art:url('${cityURL}')"><div class="eyebrow">The classic, reimagined.</div><h2>Every empire begins<br>with a single hero.</h2><p class="subtle">Recruit your army, lead it into battle, and claim all 32 towns. Choose one of the original eight heroes to begin.</p></div><div class="card-grid">${data.heroes.map((s,i)=>`<button class="hero-card" data-start="${i}" style="border-top:2px solid ${nations[s.MAIN_HERO.NATION].color}"><div class="eyebrow">${nations[s.MAIN_HERO.NATION].name}</div><h3>${esc(s.MAIN_HERO.NAME)}</h3><div class="subtle">${esc(s.MAIN_HERO.WEAPON_PRI.NAME)} · ${esc(s.CURR_TOWN)}<br>STR ${s.MAIN_HERO.STR} &nbsp; DEX ${s.MAIN_HERO.DEX} &nbsp; CON ${s.MAIN_HERO.CON}</div><div class="divider"></div><span class="badge">BEGIN CAMPAIGN →</span></button>`).join('')}</div>`;bind('[data-start]',e=>{const index=Number((e.currentTarget as HTMLElement).dataset.start);campaign=newCampaign(index);initializeEconomy(campaign,index);selected=campaign.town;save();render();notify('Campaign begun. Try a town contract to earn gold.');});}
function troopRow(key:string,hire=false,count?:number){const u=data.units[key],w=weaponStats(u);return `<div class="unit">${companyPortrait(key)}<div class="unit-copy"><b>${esc(u.NAME)}${count?` <span class="text-gold">×${count}</span>`:''}</b><small>${maxHP(u)} HP · ${w.damage}–${w.damage+Math.max(0,w.random-1)} damage<br>${esc(u.WEAPON_PRI?.NAME??'Fists')}</small></div>${hire?`<button class="tiny" data-hire="${key}" ${campaign!.gold<(u.price??0)||!world(campaign!).town||!campaign!.captured.includes(campaign!.town)?'disabled':''}>${money(u.price??0)} gp +</button>`:''}</div>`;}
function bindTown(){bind('[data-hire]',e=>{const key=(e.currentTarget as HTMLElement).dataset.hire!;if(recruit(campaign!,key)){save();render();notify(`${data.units[key].NAME} joined your army.`);}else notify('Recruitment requires an owned town, enough gold, and space in your army.');});bind('#travel',()=>travelToTown(selected));bind('#siege',()=>confirmBattle());bind('#all-troops',()=>{view='army';render();});bind('#enter-city',()=>{view='city';render();});bind('#contract',offerContract);bind('#forge',showForge);bind('#harbor',showHarbor);bind('#stables',showStables);}
function renderWorld(){
 document.querySelector('#content')!.innerHTML=atlasMarkup(campaign!,world(campaign!),selected,cityURL,worldPaused);
 const labelButton=document.querySelector<HTMLButtonElement>('#map-labels')!;
 labelButton.setAttribute('aria-pressed',String(showTownNames));
 bind('#map-labels',()=>{showTownNames=!showTownNames;labelButton.setAttribute('aria-pressed',String(showTownNames));mapScene?.townLabels.forEach(({label,essential})=>label.setVisible(showTownNames||essential));labelButton.focus({preventScroll:true});});
 bindTown();
 bind('#pause-world',()=>{worldPaused=!worldPaused;const button=document.querySelector<HTMLButtonElement>('#pause-world')!;button.textContent=worldPaused?'Resume':'Pause';button.setAttribute('aria-pressed',String(worldPaused));});
 bind('#stop-world',()=>{new WorldTravel(campaign!,rootClock).stop();save();});
 bind('#quest-route',()=>{const q=campaign!.quest!;const p=(geometry.questAvatars as Record<string,{x:number;y:number}>)[`quest_avatar_${q.avatarId}`];if(p){new WorldTravel(campaign!,rootClock).moveTo(p);worldPaused=false;render();}});
 document.querySelector('#town-select')!.addEventListener('change',e=>{selected=(e.target as HTMLSelectElement).value;pendingWorldFocus='#town-select';render();});
 game=new Phaser.Game({type:Phaser.AUTO,parent:'game',...renderDimensions(preset),transparent:true,scene:MapScene,fps:{target:preset.targetFPS,limit:preset.targetFPS},scale:{mode:Phaser.Scale.FIT,autoCenter:Phaser.Scale.CENTER_BOTH},render:{antialias:true},audio:{noAudio:true}});
}
class MapScene extends Phaser.Scene{
 avatar!:Phaser.GameObjects.Container;acc=0;travel!:WorldTravel;
 townLabels:{label:Phaser.GameObjects.Text;essential:boolean}[]=[];
 constructor(){super('map');}
 preload(){this.load.image('world',worldURL);}
 create(){mapScene=this;setupCamera(this,preset);this.add.image(403,300.5,environmentTexture(this,'world',preset)).setDisplaySize(806,601).setDepth(-10);
 // Retain the earlier painted map; source boundaries remain a quiet travel aid.
 const coast=this.add.graphics().setDepth(-9).lineStyle(1,0xffe6a0,.5),mask=geometry.masks.ground,m=mask.matrix;
 const project=(x:number,y:number)=>({x:(m.a*x+m.c*y+m.tx)/20,y:(m.b*x+m.d*y+m.ty)/20});
 for(const [left,right,,...p] of mask.edges){if(Boolean(left)===Boolean(right))continue;const start=project(p[0],p[1]);coast.beginPath();coast.moveTo(start.x,start.y);if(p.length===4){const end=project(p[2],p[3]);coast.lineTo(end.x,end.y);}else{for(let i=1;i<=16;i++){const t=i/16,u=1-t,point=project(u*u*p[0]+2*u*t*p[2]+t*t*p[4],u*u*p[1]+2*u*t*p[3]+t*t*p[5]);coast.lineTo(point.x,point.y);}}coast.strokePath();}
 Object.values(data.towns).forEach((t,index)=>{const [x,y]=(positions as Record<string,number[]>)[t.ID];const owned=campaign!.captured.includes(t.ID),sel=selected===t.ID;const color=factionColor(t.NATION);const icon=townIcon(this,x+6,y+3,color,t.adv_defenders.length>0,preset).setDepth(10+y/1000);if(y<60)icon.setScale(icon.scaleX*.7);if(owned)this.add.circle(x+6,y-4,19,0xf8d977,.35).setStrokeStyle(2,0xffefb1).setDepth(5);if(sel){const ring=this.add.ellipse(x+6,y+1,46,20).setStrokeStyle(3,0xfff5b6);if(preset.ambientMotion)this.tweens.add({targets:ring,alpha:.45,duration:1000,yoyo:true,repeat:-1});}
 {const name=this.add.text(x+6,y+15,t.NAME,{fontFamily:'Georgia',fontSize:sel?'13px':'11px',color:'#fff8dc',backgroundColor:'#284a52',padding:{x:7,y:4}}).setOrigin(.5);name.setPosition(Phaser.Math.Clamp(x+6,name.width/2+5,801-name.width/2),Math.min(575,y+17));name.setDepth(20);const essential=sel||index%5===0;name.setVisible(showTownNames||essential);this.townLabels.push({label:name,essential});}
 if(world(campaign!).town===t.ID)this.add.text(x+6,Math.max(12,y-62),'◆',{fontSize:'15px',color:'#fff5b2'}).setOrigin(.5).setDepth(21);
 if(preset.animateBanners&&index%3===0)this.tweens.add({targets:icon,angle:{from:-1,to:1},duration:1500+index*30,yoyo:true,repeat:-1});
 this.add.rectangle(x+6,y-12,Math.max(48,44*806/(document.querySelector('#game')!.getBoundingClientRect().width||806)),Math.max(56,44*806/(document.querySelector('#game')!.getBoundingClientRect().width||806)),0xffffff,0).setInteractive({useHandCursor:true}).setDepth(30).on('pointerdown',()=>{selected=t.ID;render();});
 });
 this.travel=new WorldTravel(campaign!,rootClock);const w=this.travel.state;this.avatar=this.add.container(w.x,w.y,[this.add.circle(0,0,8,0xffed92).setStrokeStyle(3,0x243e46),this.add.text(0,-17,w.sailing?'⛵':'◆',{fontSize:'20px',color:'#fff2a5'}).setOrigin(.5)]).setDepth(40);
 const q=campaign!.quest;if(q){const p=(geometry.questAvatars as Record<string,{x:number;y:number}>)[`quest_avatar_${q.avatarId}`];if(p){this.add.circle(p.x,p.y,13,0xaa3636,.85).setStrokeStyle(2,0xffe4ae).setDepth(25);this.add.text(p.x,p.y-24,'Rogues',{fontSize:'12px',color:'#fff'}).setOrigin(.5).setDepth(25);}}
 this.input.on('pointerdown',(p:Phaser.Input.Pointer,objects:Phaser.GameObjects.GameObject[])=>{if(objects.length)return;const point=this.cameras.main.getWorldPoint(p.x,p.y);if(this.travel.moveTo(point)){worldPaused=false;save();render();}});
 if(pendingWorldFocus){const selector=pendingWorldFocus;pendingWorldFocus='';requestAnimationFrame(()=>document.querySelector<HTMLElement>(selector)?.focus({preventScroll:true}));}
 }
 update(_time:number,delta:number){if(!campaign||battle||document.hidden)return;const label=document.querySelector('#journey-status');if(worldPaused){if(label)label.textContent='Journey paused';document.querySelector('#journey-light')?.classList.remove('moving');return;}this.acc+=Math.min(delta,100);while(this.acc>=1000/30){this.acc-=1000/30;const moving=!!this.travel.state.target;const event=this.travel.step();if(moving&&this.travel.state.tick%150===0)save();if(event){handleWorldEvent(event);return;}}const w=this.travel.state;this.avatar.setPosition(w.x,w.y);document.querySelector('#journey-light')?.classList.toggle('moving',!!w.target);if(label)label.textContent=`${w.sailing?'Sailing':w.town?`At ${data.towns[w.town].NAME}`:'On the road'}${w.target?' · travelling':' · at rest'}`;}
}

function renderArmy(){const c=campaign!,counts:Record<string,number>={};c.army.forEach(k=>counts[k]=(counts[k]??0)+1);const t=data.towns[c.town],closed=c.hostile.includes(t.NATION)&&!c.captured.includes(t.ID);document.querySelector('#content')!.innerHTML=`<h2 class="screen-title">Your army <span class="text-gold">/ ${c.army.length} soldiers</span></h2><div class="layout"><section class="panel"><div class="row"><h3 class="section-title">Company roster</h3><span class="chip">${c.army.length} SOLDIERS + YOUR HERO</span></div><p class="subtle">Original formations have ten troop positions plus your hero. Later reinforcements arrive one at a time as the active team drops below ten. Fallen soldiers are lost after a victory; defeat restores the pre-battle campaign.</p>${Object.entries(counts).map(([k,n])=>troopRow(k,false,n)).join('')||'<p class="empty">No troops yet. Recruit at the barracks.</p>'}</section><aside class="panel"><div class="eyebrow">${esc(c.town)}</div><h3 class="section-title" style="margin-top:9px">Local barracks</h3>${closed?'<p class="subtle">This town is hostile. Travel to a friendly town.</p>':`<div class="scroll-list">${t.barracks.map(r=>troopRow(unitKey(r),true)).join('')}</div>`}</aside></div>`;bindTown();}
function renderHero(){const c=campaign!,h=c.hero;document.querySelector('#content')!.innerHTML=`<h2 class="screen-title">${esc(h.NAME)} <span class="text-gold">/ Level ${h.LEVEL}</span></h2><div class="layout"><section class="panel"><div class="row"><div><div class="eyebrow">${nations[h.NATION].name}</div><h3 class="section-title" style="margin-top:8px">A leader in the making.</h3></div><span class="chip">${h.free_points} POINTS TO SPEND</span></div><p class="subtle">${h.LEVEL>=50?`Maximum level · ${h.EXP.toLocaleString()} experience`:`${h.EXP.toLocaleString()} / ${xpThresholds[h.LEVEL+1]?.toLocaleString()??'—'} experience`} · ${maxHP(h)} base health</p><div class="stat-grid">${(['STR','DEX','CON','INT'] as const).map(k=>`<div><b>${h[k]}</b><small>${k}</small><br><button class="tiny" style="margin-top:8px" data-stat="${k}" ${!canUpgradeAttribute(h,k)?'disabled':''}>+1</button></div>`).join('')}</div><p class="subtle">Strength improves melee damage; dexterity reduces incoming hit chance; constitution adds health; intelligence strengthens your troops.</p><div class="list-title">Skills · 1 point each; attributes · 2 points each</div><div class="card-grid">${Object.entries(h.SKILL).map(([k,n])=>`<div class="row" style="border-bottom:1px solid var(--line);padding:8px 0"><span style="font-size:13px">${esc(k)} <b class="text-gold">${n}</b></span><button class="tiny" data-skill="${k}" ${!canUpgradeSkill(h,k)?'disabled':''}>+1</button></div>`).join('')}</div></section><aside class="panel"><div class="hero-illustration" style="background-image:url('${lineupURL}')" role="img" aria-label="Representative blue-cloaked hero design"></div><div class="eyebrow">Equipped for battle</div>${(['WEAPON_PRI','WEAPON_SEC','ARMOR','HELMET'] as const).map(k=>`<div class="equipment"><small>${k.replaceAll('_',' ')}</small><b>${esc(h[k]?.NAME??'None')}</b></div>`).join('')}<p class="subtle">Buy equipment in a friendly town’s armory. Equipment requirements still apply.</p><button id="forge" class="full">Visit armory</button></aside></div>`;bind('[data-stat]',e=>{const key=(e.currentTarget as HTMLElement).dataset.stat as 'STR'|'DEX'|'CON'|'INT';if(upgradeAttribute(h,key)){save();render();}});bind('[data-skill]',e=>{const key=(e.currentTarget as HTMLElement).dataset.skill!;if(upgradeSkill(h,key)){save();render();}});bind('#forge',showForge);bind('#harbor',showHarbor);bind('#stables',showStables);}
function renderJournal(){document.querySelector('#content')!.innerHTML=`<div class="layout"><section class="panel"><div class="eyebrow">The campaign chronicle</div><h2 class="screen-title" style="margin-top:10px">A record of your rise.</h2>${campaign!.history.map(s=>`<div class="log-entry">${esc(s)}</div>`).join('')}</section><aside class="side"><section class="panel"><h3 class="section-title">Campaign saves</h3><p class="subtle">Progress saves on this device between battles. Export a backup to move between iPad and iPhone. During a battle, reloading restores the pre-battle save.</p><div class="stack"><button id="export" class="primary">Export campaign</button><button id="import">Import campaign</button><input type="file" id="import-file" accept="application/json,.json" hidden><button id="restart" class="ghost danger">Begin a new campaign</button></div></section><section class="panel"><div class="eyebrow">Research build</div><p class="subtle">Built from a JPEXS inspection of the original 2007 SWF. 76 troop definitions, 32 town tables and eight hero loadouts recovered.</p><button class="full" id="fidelity">What’s faithful?</button></section></aside></div>`;bind('#export',()=>{const blob=new Blob([JSON.stringify(campaign,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='feudalism-campaign.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);});bind('#import',()=>document.querySelector<HTMLInputElement>('#import-file')!.click());document.querySelector<HTMLInputElement>('#import-file')!.onchange=async e=>{try{const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>2_000_000)throw new Error('Save file is too large.');const candidate=readCampaignSave(await file.text());modal(`<h2>Replace this campaign?</h2><p>The imported save is ready. Export your current campaign first if you want to keep it.</p><div class="actions"><button id="cancel-import">Cancel</button><button class="primary" id="confirm-import">Import save</button></div>`);bind('#cancel-import',closeModal);bind('#confirm-import',()=>{campaign=candidate;selected=campaign.town;save();closeModal();render();notify('Campaign imported.');});}catch(err){notify((err as Error).message);}};bind('#restart',()=>{modal('<h2>A new beginning?</h2><p>This replaces your current save. Export a backup first to keep your progress.</p><div class="actions"><button id="cancel-new">Cancel</button><button id="confirm-new" class="primary">Choose a new hero</button></div>');bind('#cancel-new',closeModal);bind('#confirm-new',()=>{campaign=null;try{localStorage.removeItem(SAVE);}catch{}closeModal();render();});});bind('#fidelity',showHelp);}
function showForge(){const c=campaign!,t=data.towns[c.town];if(!servicesAvailable(c)){notify('Reach a friendly town first.');return;}if(c.hostile.includes(t.NATION)&&!c.captured.includes(t.ID)){notify('This town’s armory is closed to your army.');return;}const choices=t.forge.map(ref=>({key:ref.CATEGORY+ref.TYPE+ref.NATION+ref.LEVEL,item:data.items[ref.CATEGORY+ref.TYPE+ref.NATION+ref.LEVEL]})).filter(x=>x.item);modal(`<div class="eyebrow">Armory · ${esc(c.town)}</div><h2>Equipment shop</h2><button id="supply-shop">Potions & scrolls →</button><p>Purchases go to your inventory. Equip them there; replaced equipment is kept, and equipment restrictions apply.</p><div class="scroll-list">${choices.map(({item},i)=>`<div class="unit"><div class="unit-copy"><b>${esc(item.NAME)}</b><small>${item.value!==undefined?`${item.value} armor`:`${item.dmg??0} base damage · ${item.rng?'ranged':'melee'}`} ${item.require_param?`· ${item.require_param} ${item.require_value}`:''}</small></div><button class="tiny" data-buy="${i}" ${c.gold<item.price?'disabled':''}>${money(item.price)} gp</button></div>`).join('')}</div><br><div class="actions"><button id="close-forge">Close shop</button><button id="shop-inventory" class="primary">Open inventory</button></div>`);bind('#close-forge',closeModal);bind('#shop-inventory',()=>{closeModal();view='inventory';render();});bind('#supply-shop',showSupplies);bind('[data-buy]',e=>{const choice=choices[Number((e.currentTarget as HTMLElement).dataset.buy)];const error=buyItem(c,choice.key);if(error){notify(error);return;}save();closeModal();render();notify(`${choice.item.NAME} added to inventory.`);showForge();});}
function showSupplies(){const c=campaign!;if(!servicesAvailable(c)){notify('Reach a friendly town first.');return;}const stock=supplies(c);modal(`<h2>Potions & scrolls</h2><p>Potions heal your hero. Group healing restores living allies, including your hero. Rage speeds up troop attacks.</p><div class="scroll-list">${Object.entries(CONSUMABLES).map(([key,item])=>`<div class="unit"><div class="unit-copy"><b>${item.name} · ${stock[key as Consumable]} owned</b><small>${item.price} gp each</small></div><button data-supply-buy="${key}" data-count="1">Buy 1</button><button data-supply-buy="${key}" data-count="5">Buy 5</button></div>`).join('')}</div><button id="close-supplies" class="full">Done</button>`);bind('#close-supplies',closeModal);bind('[data-supply-buy]',e=>{const el=e.currentTarget as HTMLElement;const err=buyConsumable(c,el.dataset.supplyBuy as Consumable,Number(el.dataset.count) as 1|5);if(err){notify(err);return;}save();render();showSupplies();});}
function supplyButtons(){return Object.entries(CONSUMABLES).map(([key,item])=>`<button data-consume="${key}" ${supplies(campaign!)[key as Consumable]===0?'disabled':''}>${item.key} · ${item.name} <b>${supplies(campaign!)[key as Consumable]}</b></button>`).join('');}
function refreshSupplyButtons(){if(!campaign)return;document.querySelectorAll<HTMLButtonElement>('[data-consume]').forEach(el=>{const key=el.dataset.consume!;if(!isConsumable(key))return;el.disabled=paused||!!battle?.result||supplies(campaign!)[key]===0;el.querySelector('b')!.textContent=String(supplies(campaign!)[key]);});document.querySelectorAll<HTMLButtonElement>('[data-army-ability]').forEach(el=>{const kind=el.dataset.armyAbility as ArmyAbilityKind,remaining=battle?.armyAbilities.remainingFrames(kind);el.disabled=paused||!!battle?.result||remaining!==0;el.textContent=`${kind==='shower'?'Arrow shower':'Arrow wall'}${remaining===null?' · no reserve archers':remaining?` · ${Math.ceil(remaining/30)}s`:armyAbilityTarget===kind?' · choose target':''}`;el.setAttribute('aria-pressed',String(armyAbilityTarget===kind));});}
function selectArmyAbility(kind:ArmyAbilityKind){if(!battle||paused||battle.result||!battle.armyAbilities.ready(kind))return;armyAbilityTarget=armyAbilityTarget===kind?null:kind;refreshSupplyButtons();syncBattleHUD();if(armyAbilityTarget)notify('Tap the battlefield to target. Arrows can hit your own troops.');}
function useSupply(key:string){if(!battle||paused||battle.result||!isConsumable(key))return;battle.useConsumable(key);refreshSupplyButtons();syncBattleHUD();}
function renderInventory(){const c=campaign!,inv=economy(c).inventory;document.querySelector('#content')!.innerHTML=`<h2 class="screen-title">Inventory</h2><div class="layout"><section class="panel"><h3 class="section-title">Equipment & loot</h3><p class="subtle">Select a slot to equip an item. Replaced gear returns here. Shops buy items for half their price, rounded down.</p>${inv.length?inv.map((ref,i)=>{const item=inventoryItem(ref);const slots:Slot[]=item.TYPE==='Clothes'?['ARMOR']:item.TYPE==='Helmet'?['HELMET']:item.TYPE==='Shield'?['WEAPON_SEC']:['WEAPON_PRI','WEAPON_SEC'];return `<div class="equipment"><div class="row"><div><b>${esc(item.NAME)} ×${ref.count}</b><p class="subtle" style="margin:5px 0">${item.require_param?`Requires ${item.require_value} ${item.require_param} · `:''}${item.value!==undefined?`${item.value} defense`:`${item.dmg??0} base damage`} · Sell ${money(Math.floor(item.price/2))} gp</p></div></div><div class="actions">${slots.map(slot=>`<button data-equip="${i}" data-slot="${slot}">${slot==='WEAPON_PRI'?'Primary hand':slot==='WEAPON_SEC'?'Secondary hand':'Equip'}</button>`).join('')}<button data-sell="${i}" ${c.hostile.includes(data.towns[c.town].NATION)&&!c.captured.includes(c.town)?'disabled':''}>Sell one</button></div></div>`;}).join(''):'<p class="empty">Your inventory is empty. Buy equipment in a friendly armory or win a battle to collect loot.</p>'}</section><aside class="panel"><button id="inventory-supplies" class="full">Potions & scrolls →</button><h3 class="section-title">Currently equipped</h3>${(['WEAPON_PRI','WEAPON_SEC','ARMOR','HELMET'] as Slot[]).map(slot=>`<div class="equipment"><small>${slot.replaceAll('_',' ')}</small><div class="row"><b>${esc(c.hero[slot]?.NAME??'None')}</b><button class="tiny" data-unequip="${slot}" ${!c.hero[slot]?'disabled':''}>Remove</button></div></div>`).join('')}<p class="subtle">Two-handed weapons, shields, ranged combinations and mounted equipment follow the original restrictions.</p></aside></div>`;bind('#inventory-supplies',showSupplies);bind('[data-equip]',e=>{const el=e.currentTarget as HTMLElement;const err=equipInventory(c,Number(el.dataset.equip),el.dataset.slot as Slot);if(err)notify(err);else{save();render();}});bind('[data-unequip]',e=>{const err=unequipItem(c,(e.currentTarget as HTMLElement).dataset.unequip as Slot);if(err)notify(err);else{save();render();}});bind('[data-sell]',e=>{const err=sellItem(c,Number((e.currentTarget as HTMLElement).dataset.sell));if(err)notify(err);else{save();render();}});}

function travelToTown(town:string){const p=(geometry.towns as Record<string,{x:number;y:number}>)[town];if(!p)return;new WorldTravel(campaign!,rootClock).moveTo(p);worldPaused=false;view='world';save();render();}
function handleWorldEvent(event:WorldEvent){if(event.type==='arrive'){selected=event.town;view='city';save();render();notify(`Arrived at ${data.towns[event.town].NAME}.`);}else if(event.type==='blocked'){save();notify('The route is blocked. Choose another waypoint or use a harbor to sail.');}else{startBattle(event.enemies,event.type==='quest'?'quest':'encounter',campaign!.town,event.mapId);}}
function showHarbor(){modal(`<h2>Harbor</h2><p>Rent a ship for 4,000 gold. Sail across the sea and dock by reaching a town. Each new voyage costs another fare.</p><div class="actions"><button id="cancel-harbor">Stay ashore</button><button id="board-ship" class="primary">Board ship · 4,000 gp</button></div>`);bind('#cancel-harbor',closeModal);bind('#board-ship',()=>{const err=boardShip(campaign!);if(err){notify(err);return;}save();closeModal();view='world';render();});}
function showStables(){const c=campaign!,horses=data.towns[c.town].barn;modal(`<h2>Stables</h2><p>${c.hero.HORSE?`Current mount: ${esc(c.hero.HORSE.skin_color)} · trade-in ${Math.round(c.hero.HORSE.price/3)} gp`:'Your hero travels on foot.'}</p><div class="scroll-list">${horses.map((h,i)=>`<div class="unit"><div class="unit-copy"><b>${esc(h.skin_color)} horse</b><small>+${h.bonus_HP} HP · +${h.bonus_DEF} defense · +${h.bonus_speed} battle speed</small></div><button data-horse="${i}">${h.price} gp</button></div>`).join('')}</div><div class="actions"><button id="close-stables">Done</button><button id="sell-horse" ${!c.hero.HORSE?'disabled':''}>Sell mount</button></div>`);bind('#close-stables',closeModal);bind('[data-horse]',e=>{const err=buyHorse(c,Number((e.currentTarget as HTMLElement).dataset.horse));if(err)notify(err);else{save();render();showStables();}});bind('#sell-horse',()=>{const err=sellHorse(c);if(err)notify(err);else{save();render();showStables();}});}
function offerContract(){const c=campaign!;if(!servicesAvailable(c)){notify('Reach a friendly town hall first.');return;}const paid=collectTownReward(c);if(paid){save();render();notify(`Town hall paid ${money(paid)} gp. Purse: ${money(c.gold)} gp.`);return;}const w=world(c),active=c.quest?`Hunt ${c.quest.count} rogues, then return to ${esc(c.quest.town)} for ${c.quest.reward} gold.`:w.delivery&&w.delivery.accepted!==false?`Deliver the package to ${esc(data.towns[w.delivery.to].NAME)} for ${w.delivery.gold} gold.`:'No accepted delivery is pending.';modal(`<h2>Town hall</h2><p>${active}</p><p>Asking for new work replaces your current task and cancels its uncollected delivery payment.</p><div class="actions"><button id="close-contract">Done</button><button id="hunt-route">View map</button><button id="request-contract" class="primary">Ask for new work</button></div>`);bind('#close-contract',closeModal);bind('#hunt-route',()=>{closeModal();view='world';render();});bind('#request-contract',()=>{try{const offer=requestTownQuest(c,Math.random);save();modal(`<h2>${offer.kind==='combat'?'Clear the roads':'Deliver a package'}</h2><p>${offer.kind==='combat'?`Defeat ${offer.count} rogues and collect ${offer.reward} gp at ${esc(data.towns[offer.town].NAME)} town hall.`:`Take a package to ${esc(data.towns[offer.destination].NAME)} and collect ${offer.reward} gp at its town hall.`}</p><div class="actions"><button id="cancel-contract">Return to town</button><button id="accept-contract" class="primary">${offer.kind==='combat'?'Track rogues':'Accept delivery'}</button></div>`);bind('#cancel-contract',()=>{closeModal();render();});bind('#accept-contract',()=>{const err=approveTownQuest(c);if(err){notify(err);return;}save();closeModal();if(offer.kind==='delivery')selected=offer.destination;view='world';render();if(offer.kind==='combat')notify('Rogues marked on the map. Travel to their camp.');});}catch(error){notify((error as Error).message);}});}
function confirmBattle(){const t=data.towns[selected];modal(`<div class="eyebrow">Siege of ${esc(t.NAME)}</div><h2>Raise your banner.</h2><p>Your ${campaign!.army.length} soldiers and hero will face ${expand(t.defenders).length} garrison troops${t.adv_defenders.length?`, followed by ${expand(t.adv_defenders).length} throne-room guards`:''}. Attacking a foreign town makes its nation hostile.</p><p>Victory keeps your surviving soldiers. If your hero falls, you can restore the pre-battle campaign.</p><div class="actions"><button id="cancel-battle">Prepare more</button><button class="primary" id="confirm-battle">Begin assault ⚔</button></div>`);bind('#cancel-battle',closeModal);bind('#confirm-battle',()=>{closeModal();startBattle(expand(t.defenders),'siege',selected);});}
function createEncounter(c:Campaign,enemies:string[]|Hero[],kind:'siege'|'quest'|'throne'|'encounter',town:string,seed:number,mapOverride?:number){battleMapId=mapOverride??chooseBattleMap(kind==='encounter'?'quest':kind,town,seedRandom(seed^0x95e78d21),kind==='siege'&&world(c).shipTown===town);return new Battle(c,enemies,kind,town,seed,{heroControl:'manual',rootClock,...battleLayout(battleMapId)});}
function startBattle(enemies:string[]|Hero[],kind:'siege'|'quest'|'throne'|'encounter',town:string,mapOverride?:number){save();checkpoint=structuredClone(campaign!);battle=createEncounter(campaign!,enemies,kind,town,++campaign!.battles*7919,mapOverride);paused=false;speed=1;control='hero';armyAbilityTarget=null;resultShown=false;render();}
function syncBattleHUD(){if(battle)updateBattleHUD(battle,{paused,speed,control,armyAbilityTarget});}
function renderBattle(){const b=battle!,c=campaign!;const title=`${b.kind==='encounter'?'Road encounter':b.kind==='quest'?'Town contract':b.kind==='throne'?'Final assault':'Siege'} · ${data.towns[b.destination].NAME}`;document.querySelector('#content')!.innerHTML=battleMarkup({title,heroName:c.hero.NAME,heroLevel:c.hero.LEVEL,heroPortraitURL:lineupURL,supplyButtonsHTML:supplyButtons(),paused,speed,control:control==='army'?'army':'hero'});game=new Phaser.Game({type:Phaser.AUTO,parent:'game',...renderDimensions(preset),backgroundColor:'#e9d18d',scene:BattleScene,fps:{target:preset.targetFPS,limit:preset.targetFPS},scale:{mode:Phaser.Scale.FIT,autoCenter:Phaser.Scale.CENTER_BOTH},audio:{noAudio:true},render:{antialias:true}});bindHeroTouchControls();refreshSupplyButtons();syncBattleHUD();bind('[data-army-ability]',e=>selectArmyAbility((e.currentTarget as HTMLElement).dataset.armyAbility as ArmyAbilityKind));bind('[data-consume]',e=>useSupply((e.currentTarget as HTMLElement).dataset.consume!));bind('#pause',()=>{paused=!paused;if(paused)resetHeroControls();document.querySelector('#pause')!.textContent=paused?'Resume':'Pause';refreshSupplyButtons();syncBattleHUD();});bind('#speed',()=>{speed=speed===1?2:1;document.querySelector('#speed')!.textContent=`${speed}× Speed`;syncBattleHUD();});bind('[data-control]',e=>{control=(e.currentTarget as HTMLElement).dataset.control!;document.querySelectorAll('[data-control]').forEach(e=>e.classList.toggle('active',(e as HTMLElement).dataset.control===control));armyAbilityTarget=null;refreshSupplyButtons();syncBattleHUD();});bind('#hold',()=>{battle!.commandTroops({type:'hold'});syncBattleHUD();});bind('#charge',()=>{battle!.commandTroops({type:'charge'});syncBattleHUD();});bind('#retreat',()=>{paused=true;resetHeroControls();refreshSupplyButtons();syncBattleHUD();modal('<h2>Withdraw your army?</h2><p>This restores the campaign to its state before this battle.</p><div class="actions"><button id="continue-fight">Keep fighting</button><button class="primary" id="confirm-retreat">Withdraw</button></div>');bind('#continue-fight',()=>{paused=false;closeModal();refreshSupplyButtons();syncBattleHUD();});bind('#confirm-retreat',()=>{if(checkpoint)campaign=structuredClone(checkpoint);battle=null;checkpoint=null;closeModal();render();});});}
class BattleScene extends Phaser.Scene{
 actors=new Map<number,BattleActor>();effects!:BattleEffects;targetMarker!:Phaser.GameObjects.Graphics;acc=0;hudTime=0;clock=0;keys:Phaser.Types.Input.Keyboard.CursorKeys|null=null;wasd:Record<string,Phaser.Input.Keyboard.Key>={};
 constructor(){super('battle');}preload(){this.load.image('field',battleURL);this.load.image(COMBAT_SHEET_KEY,combatSheetURL);}
 create(){battleScene=this;setupCamera(this,preset);this.add.image(403,300.5,environmentTexture(this,'field',preset)).setDisplaySize(806,601);registerCombatFrames(this);this.drawTerrain();this.effects=new BattleEffects(this,preset);this.targetMarker=this.add.graphics().setDepth(1400);
 this.input.on('pointermove',(p:Phaser.Input.Pointer)=>{if(!armyAbilityTarget||paused||!battle||battle.result){this.targetMarker.clear();return;}const point=this.cameras.main.getWorldPoint(p.x,p.y);this.drawTarget(battleCellAt(point.x,point.y),0xef9975);});
 this.input.on('gameout',()=>this.targetMarker.clear());
 this.input.on('pointerdown',(p:Phaser.Input.Pointer)=>{if(paused||!battle||battle.result)return;const point=this.cameras.main.getWorldPoint(p.x,p.y),cell=battleCellAt(point.x,point.y);if(armyAbilityTarget){battle.castArmyAbility(armyAbilityTarget,cell);armyAbilityTarget=null;this.targetMarker.clear();refreshSupplyButtons();syncBattleHUD();return;}if(control==='hero')heroControls.moveTo(cell);else battle.commandTroops({type:'move',destination:cell});const center=battleCellCenter(cell),ring=this.add.ellipse(center.x,center.y,34,13).setStrokeStyle(2,0xffedb0).setDepth(1401);this.tweens.add({targets:ring,scale:1.4,alpha:0,duration:500,onComplete:()=>ring.destroy()});syncBattleHUD();});
 if(this.input.keyboard){this.keys=this.input.keyboard.createCursorKeys();this.wasd=this.input.keyboard.addKeys('W,A,S,D,SHIFT,ZERO,NUMPAD_ZERO') as Record<string,Phaser.Input.Keyboard.Key>;this.input.keyboard.on('keydown-P',(e:KeyboardEvent)=>{e.preventDefault();document.querySelector<HTMLButtonElement>('#pause')?.click();});}this.paint(16);syncBattleHUD();}
 drawTarget(cell:{x:number;y:number},color:number){const p=battleCellCenter(cell),g=this.targetMarker;g.clear().lineStyle(2,color,.95).strokeEllipse(p.x,p.y,44,20);g.lineBetween(p.x-27,p.y,p.x-17,p.y);g.lineBetween(p.x+17,p.y,p.x+27,p.y);g.lineBetween(p.x,p.y-16,p.x,p.y-9);g.lineBetween(p.x,p.y+9,p.x,p.y+16);}
 drawTerrain(){if(!battle)return;for(const cell of battle.blockedCells){const [x,y]=cell.split(',').map(Number),p=battleCellCenter({x,y});const g=this.add.graphics().setDepth(p.y-1);g.fillStyle(0x354d41,.2).fillEllipse(p.x+2,p.y+2,34,13);g.fillStyle(0x849281).fillPoints([{x:p.x-16,y:p.y},{x:p.x-12,y:p.y-13},{x:p.x-3,y:p.y-22},{x:p.x+11,y:p.y-17},{x:p.x+17,y:p.y-3},{x:p.x+8,y:p.y+2}],true);g.fillStyle(0xb4bf9d).fillTriangle(p.x-12,p.y-13,p.x-3,p.y-22,p.x+5,p.y-10);g.fillStyle(0x6a7e70).fillTriangle(p.x+5,p.y-10,p.x+11,p.y-17,p.x+17,p.y-3);g.lineStyle(1,0xd6d7ad,.75).lineBetween(p.x-13,p.y-2,p.x+7,p.y+1);}}
 paint(_delta:number){if(!battle)return;this.effects.paint(battle.projectiles,this.clock);for(const f of battle.fighters){let actor=this.actors.get(f.id);if(!actor){actor=new BattleActor(this,f,preset);this.actors.set(f.id,actor);}actor.paint(f,this.clock,f.team===0&&(control==='army'||f.key==='hero'));}}
 update(_time:number,delta:number){if(!battle)return;if(!paused)this.clock+=delta;this.paint(delta);if(paused||battle.result)return;this.acc+=Math.min(delta,100)*speed;while(this.acc>=1000/30){this.acc-=1000/30;const hero=battle.alive(0).find(f=>f.key==='hero');if(hero){const k=this.keys;const active=document.activeElement;const formFocused=!!active&&['INPUT','SELECT','TEXTAREA'].includes(active.tagName);const keys=!formFocused&&k?{right:k.right.isDown||this.wasd.D.isDown,left:k.left.isDown||this.wasd.A.isDown,down:k.down.isDown||this.wasd.S.isDown,up:k.up.isDown||this.wasd.W.isDown,attack:k.space.isDown||this.wasd.ZERO.isDown||this.wasd.NUMPAD_ZERO.isDown,switchWeapon:this.wasd.SHIFT.isDown}:{};battle.setHeroInput(heroControls.sample(keys,hero));}battle.step();for(const event of battle.events)this.effects.event(event);if(battle.result){showResult();break;}}
 this.hudTime+=delta;if(this.hudTime>200){this.hudTime=0;const total=document.querySelector('#army-total');if(total)total.textContent=String(battle.survivors().length);syncBattleHUD();refreshSupplyButtons();}}
}

function showResult(){if(resultShown||!battle)return;resultShown=true;paused=true;armyAbilityTarget=null;refreshSupplyButtons();syncBattleHUD();const b=battle,c=campaign!,victory=b.result==='victory';if(victory){const soldiersBefore=c.army.length,contract=b.kind==='quest'&&c.quest?{...c.quest}:null;const outcome=settleBattleVictory(b),throne=[...outcome.nextEnemies];if(!throne.length){save();checkpoint=null;}modal(`<div class="eyebrow">${c.captured.length===32?'THE WORLD IS YOURS':victory?'The field is yours':'Campaign'}</div><h2>${c.captured.length===32?'A world united.':'Victory.'}</h2><p>${throne.length?'The garrison has fallen. The throne room’s elite guards await your final assault.':b.kind==='encounter'?'Your company survived the encounter.':b.kind==='quest'?'The roads are safe again. Return to the issuing town hall to collect your contract reward.':`${esc(data.towns[b.destination].NAME)} now flies your banner.`}</p><div class="metrics"><div class="metric"><b>+${money(b.gold)} gp</b><span>Battle gold added to purse</span></div><div class="metric"><b>+${b.xp}</b><span>Experience</span></div><div class="metric"><b>${c.army.length}</b><span>Soldiers survive · ${Math.max(0,soldiersBefore-c.army.length)} lost</span></div><div class="metric"><b>${b.loot.length}</b><span>Loot items added to inventory</span></div></div>${contract?`<div class="payment-panel"><b>${money(contract.reward)} gp contract pay is waiting</b><p>Return to ${esc(data.towns[contract.town].NAME)} and use Collect payment or open Town hall. This is separate from the ${money(b.gold)} gp looted.</p></div>`:b.kind==='encounter'?'<p>This was a road encounter, not a contract battle. Any active contract is still waiting.</p>':''}<button id="end-battle" class="primary full">${throne.length?'Storm the throne room ⚔':'Return to campaign →'}</button>`);bind('#end-battle',()=>{closeModal();battle=null;selected=c.town;if(b.kind==='quest'||b.kind==='encounter')view='world';if(throne.length){battle=createEncounter(c,throne,'throne',b.destination,c.battles*7919+1);resultShown=false;paused=false;render();}else render();});}else{modal('<div class="eyebrow">Your hero has fallen</div><h2>A battle lost.</h2><p>Your pre-battle campaign is safe. Regroup, recruit more troops, or improve your equipment before trying again.</p><button id="restore-battle" class="primary full">Restore before battle →</button>');bind('#restore-battle',()=>{if(checkpoint)campaign=structuredClone(checkpoint);checkpoint=null;battle=null;closeModal();render();});}}
function renderCity(){const c=campaign!,t=data.towns[c.town],hostile=c.hostile.includes(t.NATION)&&!c.captured.includes(t.ID);document.querySelector('#content')!.innerHTML=`<div class="city-heading"><div><div class="eyebrow">${nations[t.NATION].name} · ${c.captured.includes(t.ID)?'Under your banner':'A place to prepare'}</div><h2 class="screen-title">Welcome to ${esc(t.NAME)}.</h2></div><span class="chip">${preset.label.toUpperCase()} GRAPHICS</span></div><div class="city-layout"><section class="city-stage" style="--city-art:url('${cityURL}')"><img src="${cityURL}" alt="A bright illustrated medieval city with a welcoming plaza, blue market awnings and a golden castle"><div class="city-caption"><span class="eyebrow">A little rest. A grand ambition.</span><h3>Before the next adventure.</h3><p>Gather your company, find a better blade, and hear what the townspeople need.</p></div><div class="city-hotspots"><button id="city-barracks"><span>⚑</span>Barracks</button><button id="city-armory"><span>⚒</span>Blacksmith</button><button id="city-hall"><span>✉</span>Town hall</button></div></section><aside class="side"><section class="panel"><div class="eyebrow">Recruitment & services</div><h3 class="section-title" style="margin-top:9px">Make ready.</h3>${hostile?'<p class="subtle">The gates are closed. Conquer this town before using its services.</p>':t.barracks.slice(0,3).map(r=>troopRow(unitKey(r),true)).join('')}<div class="divider"></div><p class="subtle">${nations[t.NATION].blurb}</p><button id="back-world" class="primary full">Return to world map →</button></section><section class="panel small-note"><div class="eyebrow">Visual slice 01</div><p class="subtle">One representative city environment. Regional architecture comes after this art direction is reviewed.</p></section></aside></div>`;bindTown();bind('#city-barracks',()=>{view='army';render();});bind('#city-armory',()=>showForge());bind('#city-hall',()=>{if(hostile){notify('This town is hostile.');return;}offerContract();});bind('#back-world',()=>{view='world';render();});}
function renderAtelier(){document.querySelector('#content')!.innerHTML=`<div class="art-intro"><div class="eyebrow">Art direction · Representative scenes</div><h2 class="screen-title">A brighter age of Feudalism.</h2><p class="subtle">Stylized 2.5D, hand-painted color, expressive silhouettes. Four representative scenes establish the visual direction before the wider world is remastered.</p></div><div class="art-grid">${[{key:'world',title:'01 · The known world',text:'Warm greens, clear blue seas and charming town silhouettes.',url:worldURL},{key:'battle',title:'02 · On the battlefield',text:'A readable arena, clean silhouettes and restrained combat effects.',url:battleURL},{key:'city',title:'03 · A city to call home',text:'Golden stone, generous shapes, colorful awnings and welcoming daylight.',url:cityURL}].map(s=>`<article class="art-card"><img src="${s.url}" alt="${s.text}" loading="lazy"><div><h3>${s.title}</h3><p>${s.text}</p></div></article>`).join('')}</div><section class="panel lineup-panel"><div class="row"><div><div class="eyebrow">04 · The company</div><h3 class="section-title" style="margin-top:9px">Small heroes. Great adventures.</h3></div><span class="chip">FOUR REPRESENTATIVE DESIGNS</span></div><img class="lineup-art" src="${lineupURL}" alt="Four cartoon medieval characters: blue-cloaked hero, swordsman, green-hooded archer and spearman"><div class="lineup-labels"><span>Hero</span><span>Swordsman</span><span>Archer</span><span>Spearman</span></div><p class="subtle">The design sheet sets the character language. Live combat uses four representative illustrated roles with movement, attack, hit and defeat poses. Full per-class costumes and equipment attachments are later art passes.</p></section><div class="preset-cards">${RENDER_PRESET_IDS.map(id=>{const p=RENDER_PRESETS[id];return `<button class="preset-card ${id===preset.id?'chosen':''}" data-set-preset="${id}"><span class="eyebrow">${id==='quality'?'DEFAULT':id==='battery'?'LOWEST WORKLOAD':'LIGHTER WORKLOAD'}</span><h3>${p.label}</h3><p>${p.description}</p><span class="badge">${p.targetFPS} FPS RENDER TARGET · SAME GAMEPLAY</span></button>`;}).join('')}</div><div class="notice">Stages 1–2 are active: the campaign shell, earlier painted map and representative live battlefield. City services and the full character appearance library are later stages. Physical iPad mini A17 Pro performance, heat, battery use and Safari installation remain to be tested on the device.</div>`;bind('[data-set-preset]',e=>{const id=(e.currentTarget as HTMLElement).dataset.setPreset as RenderPresetId;preset=RENDER_PRESETS[id];saveRenderPreset(id);render();});}

function resetHeroControls(){armyAbilityTarget=null;heroControls.reset();battle?.setHeroInput({x:0,y:0,attack:false,switchWeapon:false});battleScene?.input.keyboard?.resetKeys();}
function bindHeroTouchControls(){document.querySelectorAll<HTMLButtonElement>('[data-hero-action]').forEach(button=>{button.style.touchAction='none';button.addEventListener('pointerdown',e=>{e.preventDefault();if(paused||!battle||battle.result)return;button.setPointerCapture(e.pointerId);heroControls.press(e.pointerId,button.dataset.heroAction as TouchAction);});button.addEventListener('pointerup',e=>{heroControls.release(e.pointerId);});button.addEventListener('pointercancel',resetHeroControls);button.addEventListener('lostpointercapture',e=>heroControls.release(e.pointerId));});}
function suspendSession(){worldPaused=true;const journeyButton=document.querySelector('#pause-world');if(journeyButton){journeyButton.textContent='Resume';journeyButton.setAttribute('aria-pressed','true');}if(battle){paused=true;resetHeroControls();const button=document.querySelector('#pause');if(button)button.textContent='Resume';refreshSupplyButtons();syncBattleHUD();}else save();idleSceneClock.advance(0,false);}
window.addEventListener('blur',suspendSession);
window.addEventListener('pagehide',suspendSession);

window.addEventListener('keydown',e=>{const target=e.target as HTMLElement|null;if(e.repeat||e.ctrlKey||e.metaKey||e.altKey||target&&['INPUT','SELECT','TEXTAREA'].includes(target.tagName))return;const key=(Object.keys(CONSUMABLES) as Consumable[]).find(key=>CONSUMABLES[key].key===e.key);if(key&&battle&&!paused&&!battle.result){e.preventDefault();useSupply(key);}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)suspendSession();});
let previousFrame:number|undefined;
function advanceIdleScene(now:number){const delta=previousFrame===undefined?0:now-previousFrame;previousFrame=now;idleSceneClock.advance(delta,!!campaign&&!game&&!battle&&!document.hidden);requestAnimationFrame(advanceIdleScene);}
requestAnimationFrame(advanceIdleScene);
render();
if('serviceWorker' in navigator&&import.meta.env.PROD){window.addEventListener('load',()=>{
 navigator.serviceWorker.register(new URL('./sw.js',document.baseURI),{scope:'./',updateViaCache:'none'}).then(registration=>{
  const updateNotice=()=>{if(registration.waiting)notify('An update is ready. Finish your session, then close all game windows and reopen.');};
  updateNotice();registration.addEventListener('updatefound',()=>{const worker=registration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)updateNotice();});});
  void registration.update().catch(()=>{});
  return navigator.serviceWorker.ready;
 }).then(()=>notify('Offline cache ready. Add to Home Screen from Safari.')).catch(()=>notify('Offline cache could not be prepared. This session needs a connection.'));
});}
